    "C195", "C212", "C216", "C219", "C267"
  ],
  "claims": [
    {
      "claim": "Transferable direct low-F outcomes from polar/lactone-containing molecules—EM574 (~2% in humans), naringin (5–9% in humans), 9-nitrocamptothecin (very low/erratic in humans), tigecycline (<1%), and 5-hydroxyrofecoxib (~14–15% in humans)—support F < 20% for this highly polar, rigid polycyclic trilactone query.",
      "card_ids": ["C01", "C07", "C15", "C05", "C12", "C14", "C03", "C13", "C02", "C29", "C09", "C11"]
    },
    {
      "claim": "L5 gut-wall evidence in related terpene lactones and camptothecins shows low absorptive permeability and efflux (triptolide PappAB 1.62×10^-6 cm/s with ER 1.87 and 2.15×10^-7 cm/s with ER 2.70 at 2 µM; bilobalide absorptive Papp 2.11×10^-6 cm/s with secretory 5.13×10^-6 cm/s; camptothecins as BCRP/P-gp substrates with Papp ~5.8×10^-6 cm/s), coherently supporting presystemic loss.",
      "card_ids": ["C195", "C212", "C216", "C172", "C218", "C213", "C214"]
    },
    {
      "claim": "L6 hepatic-metabolism records show that related terpene lactones and lactone-containing drugs undergo CYP-mediated hepatic metabolism (triptolide CYP3A4 hydroxylation with rat liver microsomal half-life 35.7 min; artemisinin CYP3A4/5 hydroxylation; simvastatin CYP3A4/PON1 metabolism), adding mechanistic support for hepatic first-pass liability, though no query-specific hepatic data are present.",
      "card_ids": ["C219", "C267", "C221", "C226", "C260", "C262", "C253"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C219", "C267", "C221", "C226", "C260", "C262", "C253"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability, permeability, solubility, or first-pass metabolism data for the query molecule.",
    "L6 hepatic-clearance records are for other molecules (triptolide, artemisinin, simvastatin, macrolides, camptothecins), not ginkgolide C; transfer is qualitative and species/assay-dependent.",
    "No human PK or matched oral/IV exposure data for the query.",
    "No query-specific gut-wall efflux, intestinal metabolism, or hepatic clearance measurements.",
    "Formulation and dose effects on the query are unknown."
  ],
  "decision_summary": "L6 adds indirect hepatic-metabolism evidence for related terpene lactones and lactone-containing drugs, supporting hepatic first-pass liability, but no query-specific data. Combined with transferable direct low-F outcomes and L5 gut-wall permeability/efflux evidence, F<20% remains better supported. Predict low with moderate confidence."
}

